namespace sv_615d700f3aa44583819a23ea3aa3f190.Services;

public class WarehouseState
{
    private string _currentWarehouseId = "warehouse-a";
    private string _currentWarehouseName = "Warehouse A";

    public string CurrentWarehouseId => _currentWarehouseId;
    public string CurrentWarehouseName => _currentWarehouseName;

    public event Action? OnChange;

    public static readonly (string Id, string Name)[] AvailableWarehouses =
    [
        ("warehouse-a", "Warehouse A"),
        ("warehouse-b", "Warehouse B"),
        ("warehouse-c", "Warehouse C"),
        ("warehouse-d", "Warehouse D"),
    ];

    public void SetWarehouse(string warehouseId, string warehouseName)
    {
        if (_currentWarehouseId == warehouseId) return;

        _currentWarehouseId = warehouseId;
        _currentWarehouseName = warehouseName;
        OnChange?.Invoke();
    }
}

namespace sv_615d700f3aa44583819a23ea3aa3f190.Services;

/// <summary>
/// Scoped service that polls for low-stock alerts and notifies all subscribers.
/// Scoped lifetime ensures each user circuit gets its own independent instance.
/// </summary>
public class InventoryAlertService : IDisposable
{
    private readonly WarehouseState _warehouseState;
    private readonly Random _random = new();

    private PeriodicTimer? _timer;
    private CancellationTokenSource? _cts;
    private int _subscriberCount;
    private int _lastLowStockCount;

    public int LowStockCount => _lastLowStockCount;

    public event Action? OnAlertCountChanged;

    public InventoryAlertService(WarehouseState warehouseState)
    {
        _warehouseState = warehouseState;
        _warehouseState.OnChange += HandleWarehouseChanged;
    }

    /// <summary>
    /// Simulates a database query returning low-stock item count for a warehouse.
    /// </summary>
    public Task<int> GetLowStockCountAsync(string warehouseId)
    {
        return Task.FromResult(_random.Next(0, 16));
    }

    /// <summary>
    /// Called by components when they become visible and want polling to run.
    /// Polling starts on the first subscriber and stops when all unsubscribe.
    /// </summary>
    public void StartPolling()
    {
        _subscriberCount++;
        if (_subscriberCount == 1)
        {
            _cts = new CancellationTokenSource();
            _timer = new PeriodicTimer(TimeSpan.FromSeconds(10));
            _ = PollLoopAsync(_cts.Token);
        }
    }

    /// <summary>
    /// Called by components when they are disposed or leave visibility.
    /// </summary>
    public void StopPolling()
    {
        _subscriberCount = Math.Max(0, _subscriberCount - 1);
        if (_subscriberCount == 0)
        {
            CancelPolling();
        }
    }

    /// <summary>
    /// Forces an immediate refresh of alert data (e.g., after warehouse change).
    /// </summary>
    public async Task RefreshAsync()
    {
        var count = await GetLowStockCountAsync(_warehouseState.CurrentWarehouseId);
        _lastLowStockCount = count;
        OnAlertCountChanged?.Invoke();
    }

    private async Task PollLoopAsync(CancellationToken ct)
    {
        // Immediate first poll
        await RefreshAsync();

        while (!ct.IsCancellationRequested)
        {
            try
            {
                if (!await _timer!.WaitForNextTickAsync(ct))
                    break;

                await RefreshAsync();
            }
            catch (OperationCanceledException)
            {
                break;
            }
        }
    }

    private void HandleWarehouseChanged()
    {
        if (_subscriberCount > 0)
        {
            _ = RefreshAsync();
        }
    }

    private void CancelPolling()
    {
        _cts?.Cancel();
        _cts?.Dispose();
        _cts = null;
        _timer?.Dispose();
        _timer = null;
    }

    public void Dispose()
    {
        _warehouseState.OnChange -= HandleWarehouseChanged;
        CancelPolling();
    }
}

