@rendermode InteractiveServer
@inject WarehouseState WarehouseState
@implements IDisposable

<div class="warehouse-selector">
    <label class="form-label mb-0 me-2 text-white" for="warehouseSelect">Site:</label>
    <select id="warehouseSelect" class="form-select form-select-sm" style="width: auto; display: inline-block;"
            value="@WarehouseState.CurrentWarehouseId" @onchange="OnWarehouseChanged">
        @foreach (var wh in WarehouseState.AvailableWarehouses)
        {
            <option value="@wh.Id">@wh.Name</option>
        }
    </select>
</div>

@code {
    private Action? _handler;

    protected override void OnInitialized()
    {
        _handler = () => InvokeAsync(StateHasChanged);
        WarehouseState.OnChange += _handler;
    }

    private void OnWarehouseChanged(ChangeEventArgs e)
    {
        var selectedId = e.Value?.ToString();
        if (selectedId is null) return;

        var warehouse = WarehouseState.AvailableWarehouses.FirstOrDefault(w => w.Id == selectedId);
        if (warehouse != default)
        {
            WarehouseState.SetWarehouse(warehouse.Id, warehouse.Name);
        }
    }

    public void Dispose() => WarehouseState.OnChange -= _handler;
}

